using System;using System.IO;using System.Linq;using System.Text;using System.Threading;using System.Diagnostics;using System.Collections.Generic;using System.Security.Principal;using System.Security.AccessControl;using System.Security.Cryptography;using System.Runtime.InteropServices;using System.Web.Script.Serialization;
public sealed class MuStorageException:IOException {public string Code;public MuStorageException(string code,string message):base(message){Code=code;}}
// Exact production admission/action/factory methods are appended by the PS
// fixture. Registration, power, ACL and Hyper-V are explicit adapters; all copy,
// receipt, pin/rename/disposition and operation-lock I/O is real Windows I/O.
public static partial class MuHyperVBroker {
    static readonly object Gate=new object();static readonly Dictionary<string,Dictionary<string,object>> Records=new Dictionary<string,Dictionary<string,object>>();static readonly Dictionary<string,object> Gates=new Dictionary<string,object>();
    static CancellationTokenSource Closing=new CancellationTokenSource(),PowerCancellation=new CancellationTokenSource();
    static string Root,OwnerSid="S-1-5-21-1-2-3-1001",VmState="Off",Mode="",CopyPoint;static int DependencyCalls,FailDependencyAt;
    static Action OnDependency;static ManualResetEvent Entered,Release;
    static JavaScriptSerializer Json(){return new JavaScriptSerializer{MaxJsonLength=2097152,RecursionLimit=20};}
    static void ValidateKeys(Dictionary<string,object> value,params string[] names){if(value.Keys.Any(name=>!names.Contains(name)))throw new ArgumentException("Unexpected request field");}
    static string Text(Dictionary<string,object> value,string key,int max){object raw;if(!value.TryGetValue(key,out raw)||!(raw is string)||((string)raw).Length<1||((string)raw).Length>max||((string)raw).IndexOf('\0')>=0)throw new ArgumentException("Text rejected");return (string)raw;}
    static string Id(Dictionary<string,object> value){string id=Text(value,"id",36);Guid parsed;if(!Guid.TryParseExact(id,"D",out parsed)||parsed==Guid.Empty||parsed.ToString("D")!=id)throw new ArgumentException("Identity rejected");return id;}
    static int Number(Dictionary<string,object> value,string key,int min,int max){object raw;if(!value.TryGetValue(key,out raw)||!(raw is int)&&!(raw is long)||Convert.ToInt64(raw)<min||Convert.ToInt64(raw)>max)throw new ArgumentException("Number rejected");return Convert.ToInt32(raw);}
    static string Digest(Dictionary<string,object> value,string key){string digest=Text(value,key,64);if(digest.Length!=64||digest.Any(c=>!"abcdef0123456789".Contains(c)))throw new ArgumentException("Digest rejected");return digest;}
    static object VmGate(string id){lock(Gate){object value;if(!Gates.TryGetValue(id,out value)){value=new object();Gates.Add(id,value);}return value;}}
    static Dictionary<string,object> Owned(string id){lock(Gate){Dictionary<string,object> value;if(!Records.TryGetValue(id,out value)||Convert.ToString(value["ownerSid"])!=OwnerSid)throw new UnauthorizedAccessException("Owner changed");return value;}}
    static void CheckPower(){PowerCancellation.Token.ThrowIfCancellationRequested();}
    static bool HostServicingBusy(){return false;}
    static void CheckBackupBusy(string id,string action){}
    static void RestorePending(string id,string action){}
    static object GrowthJournal(Dictionary<string,object> record){return null;}
    static Dictionary<string,object> Parameters(Dictionary<string,object> record){string allocation=Path.Combine(Root,Id(record));return new Dictionary<string,object>{{"directory",allocation},{"disk",Path.Combine(allocation,"disk.vhdx")},{"seed",Path.Combine(allocation,"seed.iso")}};}
    static void SnapshotPending(string id,string action){if(Directory.Exists(Path.Combine(Convert.ToString(Parameters(Owned(id))["directory"]),"snapshots","restore-active")))throw new MuStorageException("SNAPSHOT_PENDING","Existing restore retained");}
    sealed class Lease:IDisposable {public void Dispose(){}}
    static IDisposable SnapshotPin(Dictionary<string,object> record){Owned(Id(record));return new Lease();}
    static void ValidateStagingPath(string path,bool directory){if(!Path.GetFullPath(path).StartsWith(Root+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new UnauthorizedAccessException("Fixture boundary");var flags=System.IO.File.GetAttributes(path);if((flags&FileAttributes.ReparsePoint)!=0||((flags&FileAttributes.Directory)!=0)!=directory)throw new IOException("Fixture entry changed");}
    static byte[] StagingCreationSecurity(bool directory){var sid=WindowsIdentity.GetCurrent().User;FileSystemSecurity acl=directory?(FileSystemSecurity)new DirectorySecurity():new FileSecurity();acl.SetOwner(sid);acl.SetAccessRuleProtection(true,false);acl.AddAccessRule(new FileSystemAccessRule(sid,FileSystemRights.FullControl,directory?InheritanceFlags.ContainerInherit|InheritanceFlags.ObjectInherit:InheritanceFlags.None,PropagationFlags.None,AccessControlType.Allow));return acl.GetSecurityDescriptorBinaryForm();}
    static MuOfflineSnapshotStore SnapshotStore(Dictionary<string,object> record,CancellationToken cancel){var parameters=Parameters(record);string allocation=Convert.ToString(parameters["directory"]);return new MuOfflineSnapshotStore(allocation,Id(record),path=>Directory.CreateDirectory(path),path=>new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.Read),bytes=>{},()=>{cancel.ThrowIfCancellationRequested();if(VmState!="Off")throw new IOException("Not Off");},point=>{if(point==CopyPoint)throw new OperationCanceledException("Synthetic unpublished copy");},SnapshotStagingStore(record));}
    static string Invoke(string action,Dictionary<string,object> parameters,int timeout,CancellationToken cancel){
        cancel.ThrowIfCancellationRequested();if(action=="review-allocation"){if(VmState!="Off")throw new IOException("VM stop state not confirmed");return Json().Serialize(new{platformId="87654321-4321-4321-8321-210987654321"});}
        if(action!="review-snapshot-staging")throw new InvalidOperationException("Unexpected provider operation");DependencyCalls++;
        if(Mode=="blocked"){Entered.Set();Release.WaitOne(20000);}if(OnDependency!=null)OnDependency();if(FailDependencyAt==DependencyCalls)throw new IOException("Synthetic dependency provider failure");
        return Json().Serialize(new{platformId=Mode=="foreign-vm"?Guid.NewGuid().ToString("D"):"87654321-4321-4321-8321-210987654321",snapshotId=Mode=="foreign-copy"?Guid.NewGuid().ToString("D"):parameters["snapshotId"],state=Mode=="running-receipt"?"Running":"Off",cpus=Mode=="wrong-resources"?2:1,memoryGiB=2,diskGiB=16,unreferenced=Mode!="referenced"});
    }
    static void Require(bool value,string message){if(!value)throw new InvalidOperationException(message);}
    static bool Fails(Action work){try{work();return false;}catch(IOException){return true;}catch(InvalidDataException){return true;}catch(UnauthorizedAccessException){return true;}catch(ArgumentException){return true;}catch(OperationCanceledException){return true;}}
    static string Hash(string path){using(var hash=SHA256.Create())using(var file=System.IO.File.OpenRead(path))return Convert.ToBase64String(hash.ComputeHash(file));}
    sealed class Case {
        public Dictionary<string,object> record;public string id,copyId,path;
        public Case(string root){Root=root;Directory.CreateDirectory(root);Records.Clear();Gates.Clear();Closing.Dispose();PowerCancellation.Dispose();Closing=new CancellationTokenSource();PowerCancellation=new CancellationTokenSource();VmState="Off";Mode="";OnDependency=null;CopyPoint=null;FailDependencyAt=DependencyCalls=0;id=Guid.NewGuid().ToString("D");record=new Dictionary<string,object>{{"id",id},{"ownerSid",OwnerSid},{"platformId","87654321-4321-4321-8321-210987654321"},{"stage","ready"},{"cpus",1},{"memoryGiB",2},{"diskGiB",16}};Records.Add(id,record);string allocation=Convert.ToString(Parameters(record)["directory"]);Directory.CreateDirectory(allocation);System.IO.File.WriteAllBytes(Path.Combine(allocation,"disk.vhdx"),Enumerable.Repeat((byte)61,2097171).ToArray());System.IO.File.WriteAllBytes(Path.Combine(allocation,"seed.iso"),Enumerable.Repeat((byte)62,65536).ToArray());CopyPoint="create-before-publish";try{SnapshotStore(record,CancellationToken.None).Create("native-owned","opaque-configuration",CancellationToken.None);}catch(OperationCanceledException){}CopyPoint=null;path=Directory.GetDirectories(Path.Combine(allocation,"snapshots"),"create-next-*").Single();copyId=Path.GetFileName(path).Substring("create-next-".Length);}
        public string[] Sources(){var p=Parameters(record);return new[]{Hash(Convert.ToString(p["disk"])),Hash(Convert.ToString(p["seed"]))};}
        public Dictionary<string,object> Request(bool cleanup,MuSnapshotStaging.Review review=null,bool resume=false){var request=new Dictionary<string,object>{{"action",cleanup?"snapshot-staging-cleanup":"snapshot-staging-review"},{"id",id},{"copyId",copyId},{"operation","create"}};if(cleanup){request["token"]=review.token;request["resumeOnly"]=resume;}return request;}
        public MuSnapshotStaging.Review Review(){return (MuSnapshotStaging.Review)SnapshotStagingAction("snapshot-staging-review",Request(false),CancellationToken.None);}
        public object Cleanup(MuSnapshotStaging.Review review,bool resume=false){return SnapshotStagingAction("snapshot-staging-cleanup",Request(true,review,resume),CancellationToken.None);}
        public void Intact(){Require(Directory.GetFiles(path).Length==3,"Refused action deleted original staging files");Require(!SnapshotLiveDeletes.ContainsKey(id),"Action leaked its admission fence");}
    }
    public static string RunStagingBridge(string root){var checks=new List<object>();int number=0;Action<string,Action<Case>> test=(name,work)=>{var c=new Case(Path.Combine(root,(++number).ToString()));try{work(c);}catch(Exception error){throw new InvalidOperationException(name+": "+error.Message,error);}checks.Add(new{name=name,passed=true});};
        test("actual-action-reviews-before-confirmed-original-cleanup",c=>{var before=c.Sources();var review=c.Review();Require(review.id==c.copyId&&review.phase=="copy"&&review.files==3,"Review receipt changed");c.Intact();var result=(MuSnapshotStaging.CleanupReceipt)c.Cleanup(review);Require(result.deleted&&!Directory.Exists(c.path)&&c.Sources().SequenceEqual(before),"Cleanup altered source or missed copy");});
        foreach(string mode in new[]{"foreign-vm","foreign-copy","running-receipt","referenced","wrong-resources"}){string value=mode;test("dependency-receipt-refused-"+mode,c=>{Mode=value;Require(Fails(()=>c.Review()),"Unsafe review issued");c.Intact();});}
        test("running-source-cannot-review-or-clean",c=>{var review=c.Review();VmState="Running";Require(Fails(()=>c.Review())&&Fails(()=>c.Cleanup(review)),"Running source admitted");VmState="Off";c.Intact();});
        test("original-plan-resumes-after-provider-loss-between-files",c=>{var before=c.Sources();var review=c.Review();DependencyCalls=0;FailDependencyAt=3;Require(Fails(()=>c.Cleanup(review)),"Provider loss ignored");Require(!System.IO.File.Exists(Path.Combine(c.path,"disk.vhdx")),"Interruption did not follow first original delete");FailDependencyAt=0;var pending=c.Review();Require(pending.phase=="deleting"&&pending.files==2,"Original deletion plan lost");c.Cleanup(pending,true);Require(!Directory.Exists(c.path)&&c.Sources().SequenceEqual(before),"Resume changed current source");});
        test("request-cannot-inject-a-host-path",c=>{var request=c.Request(false);request["path"]=Path.GetPathRoot(c.path);Require(Fails(()=>SnapshotStagingAction("snapshot-staging-review",request,CancellationToken.None)),"Caller path accepted");c.Intact();});
        test("record-object-replacement-invalidates-a-held-review",c=>{OnDependency=()=>{Records[c.id]=new Dictionary<string,object>(c.record);OnDependency=null;};Require(Fails(()=>c.Review()),"Replaced allocation object adopted");c.Intact();});
        test("power-revocation-keeps-original-copy",c=>{var review=c.Review();PowerCancellation.Cancel();Require(Fails(()=>c.Cleanup(review)),"Power loss ignored");c.Intact();});
        test("active-restore-tree-fences-staging-cleanup",c=>{Directory.CreateDirectory(Path.Combine(Path.GetDirectoryName(c.path),"restore-active"));Require(Fails(()=>c.Review()),"Unresolved restore bypassed");c.Intact();});
        test("stop-cancels-blocked-provider-without-taking-vm-gate-or-joining",c=>{
            Mode="blocked";Entered=new ManualResetEvent(false);Release=new ManualResetEvent(false);Exception failure=null;var worker=new Thread(()=>{try{c.Review();}catch(Exception error){failure=error;}});worker.Start();try{
                Require(Entered.WaitOne(10000),"Provider did not reach bounded wait");bool taken=Monitor.TryEnter(VmGate(c.id),100);Require(taken,"Provider held VmGate");if(taken)Monitor.Exit(VmGate(c.id));
                Require(Fails(()=>SnapshotLiveAdmission(c.id,"start",new Dictionary<string,object>{{"action","start"},{"id",c.id}})),"Concurrent mutation was admitted");var clock=Stopwatch.StartNew();SnapshotLiveAdmission(c.id,"stop",new Dictionary<string,object>{{"action","stop"},{"id",c.id}});Require(clock.ElapsedMilliseconds<500&&worker.IsAlive,"Stop joined blocked provider");Release.Set();Require(worker.Join(10000),"Cancelled worker did not retire");Require(failure is OperationCanceledException,"Late receipt escaped stop cancellation");c.Intact();
            }finally{Release.Set();worker.Join(10000);Entered.Dispose();Release.Dispose();}
        });
        return Json().Serialize(new{complete=true,actualProductionAction=true,actualProducerAndCleanup=true,actualKernelFileOperations=true,actualHyperV=false,protectedAcl=false,checks=checks});
    }
}
